def assert_round_trip_count(result: TreeNode[int] | None, expected_count: int) -> bool:
    def count(node: TreeNode[int] | None) -> int:
        if node is None:
            return 0
        return 1 + count(node.left) + count(node.right)

    assert count(result) == expected_count
    return True
